 function fillBrokerage(sideKey,value){const target=String(value||"").trim().toLowerCase();const match=brokerageDirectory.find(b=>String(b.brokerage_name||b.company_name||b.name||"").trim().toLowerCase()===target);if(match){setForm(v=>({...v,[sideKey+"_name"]:match.brokerage_name||match.company_name||match.name,[sideKey+"_address"]:[match.address,match.unit&&("Unit "+match.unit),match.city,match.province,match.postal_code].filter(Boolean).join(", "),[sideKey+"_phone"]:match.phone||match.telephone||"",[sideKey+"_fax"]:match.fax||""}));return}const contact=brokerageContacts.find(c=>contactCompany(c).toLowerCase()===target);if(contact)setForm(v=>({...v,[sideKey+"_name"]:contactCompany(contact),[sideKey+"_address"]:contactAddress(contact),[sideKey+"_phone"]:contactPhone(contact),[sideKey+"_fax"]:contact.fax||contact.fax_number||""}));}
