 function applyRepresentingDefaults(values){const v={...values};const side=v.side||"SELLER";const isBuyer=["BUYER","TENANT"].includes(side);const fullName=[representingAgent?.first_name,representingAgent?.last_name].filter(Boolean).join(" ")||representingAgent?.full_name||representingAgent?.name||user?.user_metadata?.full_name||user?.email||"";const agentEmail=representingAgent?.email||user?.email||"";const agentPhone=representingAgent?.phone||representingAgent?.mobile||representingAgent?.cell_phone||representingAgent?.telephone||"";const brokerageName=companyProfile?.name||companyProfile?.company_name||"DREAM VALLEY REALTY INC., BROKERAGE";const brokerageAddress=[companyProfile?.address,companyProfile?.address_line_1,companyProfile?.city,companyProfile?.province,companyProfile?.postal_code].filter(Boolean).join(", ");const brokeragePhone=companyProfile?.phone||companyProfile?.telephone||"(416) 951-9929";if(isBuyer){v.buyer_brokerage_name=brokerageName;v.buyer_brokerage_address=brokerageAddress;v.buyer_brokerage_phone=brokeragePhone;v.buyer_agent_name=fullName;v.buyer_agent_phone=agentPhone;v.buyer_agent_email=agentEmail;}else{v.listing_brokerage_name=brokerageName;v.listing_brokerage_address=brokerageAddress;v.listing_brokerage_phone=brokeragePhone;v.listing_agent_name=fullName;v.listing_agent_phone=agentPhone;v.listing_agent_email=agentEmail;}return v;}
